(()=>{
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)],config=window.STORE_CONFIG;let sugar='low';
function message(text){$('.template-message')?.remove();const box=document.createElement('div');box.className='template-message';box.role='status';box.textContent=text;document.body.append(box);setTimeout(()=>box.remove(),6500);}
$$('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(form.hasAttribute('data-buybox-form')&&config.checkoutUrl){location.assign(config.checkoutUrl);return;}message(form.hasAttribute('data-buybox-form')?'Store checkout is not connected yet.':'Signup is not connected yet.');}));
$$('a').forEach(a=>{const href=a.getAttribute('href')||'';if(href&&!href.startsWith('#')&&!href.startsWith('/assets/'))a.addEventListener('click',e=>{e.preventDefault();message('This link can be connected when you customize your store.');});});
$$('[data-trigger]').forEach(b=>b.addEventListener('click',()=>{const panel=document.getElementById(b.getAttribute('aria-controls'))||$('[data-panel]',b.closest('accordion-item,footer-nav'));const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));if(panel){panel.style.gridTemplateRows=open?'1fr':'0fr';panel.hidden=false;}}));
function prices(){const retail=sugar==='low'?config.lowSugarRetail:config.sugarFreeRetail;const first=retail*(1-config.subscriptionDiscountPercent/100);const values={'subscription-one':first,'subscription-two':first*2-config.twoPersonDiscount,'one-time':retail};const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:config.currency}).format(x);
Object.entries(values).forEach(([key,val])=>{$$('[data-price="'+key+'"]').forEach(e=>e.textContent=money(val));$$('[data-compare-price="'+key+'"]').forEach(e=>e.textContent=money(retail*(key==='subscription-two'?2:1)));$$('[data-daily-price="'+key+'"]').forEach(e=>e.textContent=money(val/(key==='subscription-two'?56:28))+' Per Day');$$('[data-discount-badge="'+key+'"]').forEach(e=>e.textContent=Math.round((1-val/(retail*(key==='subscription-two'?2:1)))*100)+'% off');});}
$$('[data-sugar-option]').forEach(b=>b.addEventListener('click',()=>{sugar=b.dataset.sugarOption;$$('[data-sugar-option]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-sugar-media]').forEach(x=>x.classList.toggle('hidden',x.dataset.sugarMedia!==sugar));prices();}));prices();
$$('[data-purchase-option]').forEach(input=>input.addEventListener('change',()=>{$$('[data-pack-copy]').forEach(e=>e.textContent=input.value==='subscription-two'?e.dataset.twoPersonCopy:e.dataset.onePersonCopy);const button=$('[data-add-to-cart]');const slot=$('[data-cta-slot="'+(input.value==='one-time'?'one-time':'subscription')+'"]');if(slot&&button)slot.append(button);}));
const slides=$$('[data-gallery-slide]');const slideParent=slides[0]?.parentElement;let index=0;function slide(n){index=(n+slides.length)%slides.length;if(slideParent){slideParent.style.transition='transform .35s';slideParent.style.transform='translateX(-'+index*100+'%)';}$$('button[data-slide-index]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.slideIndex)===index)));}
$$('button[data-slide-index]').forEach(b=>b.addEventListener('click',()=>slide(Number(b.dataset.slideIndex))));
const modal=$('[data-nutrition-modal]');function nutrition(open){if(!modal)return;modal.hidden=!open;if(open&&!modal.open)modal.showModal();if(!open&&modal.open)modal.close();modal.classList.toggle('hidden',!open);modal.setAttribute('aria-hidden',String(!open));if(open)$('[data-nutrition-close]',modal)?.focus();}
$$('[data-nutrition-open]').forEach(b=>b.addEventListener('click',()=>nutrition(true)));$$('[data-nutrition-close]').forEach(b=>b.addEventListener('click',()=>nutrition(false)));nutrition(false);
$$('[data-nutrition-sugar]').forEach(b=>b.addEventListener('click',()=>{$$('[data-nutrition-media]').forEach(e=>e.classList.toggle('hidden',e.dataset.nutritionMedia!==b.dataset.nutritionSugar));}));
const drawer=$('[data-header-menu-drawer]');function menu(open){if(!drawer)return;drawer.hidden=!open;drawer.dataset.open=String(open);drawer.classList.toggle('hidden',!open);drawer.style.visibility=open?'visible':'hidden';drawer.style.opacity=open?'1':'0';drawer.style.pointerEvents=open?'auto':'none';const p=$('[data-header-menu-panel]',drawer);if(p)p.style.transform=open?'translateX(0)':'';$$('[data-header-menu-open]').forEach(b=>b.setAttribute('aria-expanded',String(open)));}
$$('[data-header-menu-open]').forEach(b=>b.addEventListener('click',()=>menu(true)));$$('[data-header-menu-close],[data-header-menu-overlay]').forEach(b=>b.addEventListener('click',()=>menu(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nutrition(false);menu(false);}});
$$('[data-marquee-toggle]').forEach(b=>b.addEventListener('click',()=>{const track=$('[data-marquee-track]',b.closest('marquee-section'));if(track)track.style.animationPlayState=track.style.animationPlayState==='paused'?'running':'paused';}));
$$('.show-email-btn').forEach(b=>b.addEventListener('click',()=>{const form=$('form',b.closest('newsletter-form'));const input=$('input[type=tel],input[type=email]',form);input.type=input.type==='email'?'tel':'email';input.placeholder=input.type==='email'?'Email Address':'Phone Number';input.setAttribute('aria-label',input.placeholder);b.textContent=input.type==='email'?'Text me instead.':'Email me instead.';}));
})();

(()=>{document.querySelectorAll('embla-carousel').forEach(carousel=>{const track=carousel.querySelector('.embla__container');if(!track)return;const viewport=track.parentElement;viewport.style.overflowX='auto';viewport.style.scrollSnapType='x mandatory';track.querySelectorAll('.embla__slide').forEach(s=>s.style.scrollSnapAlign='start');carousel.querySelectorAll('button').forEach(b=>{const label=b.getAttribute('aria-label')||'';if(/slide/i.test(label))b.addEventListener('click',()=>viewport.scrollBy({left:(/previous/i.test(label)?-1:1)*(track.firstElementChild.getBoundingClientRect().width+24),behavior:'smooth'}));});});const ctx=document.modelContext;if(ctx?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(ctx.registerTool({name:'configure_product',description:'Select a sugar level and purchase option on the template; does not place an order.',inputSchema:{type:'object',properties:{sugar:{type:'string',enum:['low','sugar-free']},purchase:{type:'string',enum:['subscription-one','subscription-two','one-time']}},required:['sugar','purchase'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!['low','sugar-free'].includes(input.sugar)||!['subscription-one','subscription-two','one-time'].includes(input.purchase))throw new Error('Invalid product selection');document.querySelector('[data-sugar-option="'+input.sugar+'"]').click();document.querySelector('[data-purchase-option][value="'+input.purchase+'"]').click();return {sugar:input.sugar,purchase:input.purchase,checkoutConnected:Boolean(window.STORE_CONFIG.checkoutUrl)};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}})();